using System.Collections.Generic;
using LittleLeo;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "RearmAction", menuName = "Data/Battle/Battle Actions/Hevelius/Rearm Action")]
public class RearmAction : BattleAction
{
	[Header("Achievement")]
	[SerializeField]
	private AchievementData astralTinkererAchievementData;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		return ReferenceSingleton<AssetsReference>.Instance.CurrentCompanions.ActiveCompanions.Count > 0;
	}

	public override void AreaCastTarget(List<GameObject> targets, GameObject source)
	{
		if (ReferenceSingleton<GameStateManager>.Instance.CurrentState != ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState)
		{
			ReferenceSingleton<GameStateManager>.Instance.SetNoInteractionState();
		}
		if (ReferenceSingleton<BattleHandler>.Instance.IsSourceCompanions(source))
		{
			ReferenceSingleton<CursorHandler>.Instance.ToggleCursor(value: true);
			SetupCurrentActionInstance();
		}
		InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, ReferenceSingleton<BattleHandler>.Instance.FramesToWaitToUpdateCorruption + 1, delegate
		{
			targets.RemoveAll((GameObject obj) => obj.GetComponent<CorruptionStats>().IsDefeated());
			if (targets.Count > 0)
			{
				CheckAstralTinkererAchievement();
				List<DiceInstance> list = new List<DiceInstance>();
				for (int i = 0; i < targets.Count; i++)
				{
					CompanionAbility component = targets[i].GetComponent<CompanionAbility>();
					list.AddRange(SetupDiceInstances(component, ignoreCurrentDiceInstance: true));
					SpawnVFX(GetVFXOwnerPosition(targets[i]), 4f);
				}
				if (IsVFXEnabled())
				{
					PlaySFX();
				}
				ReferenceSingleton<AssetsReference>.Instance.RerollAction.ExternalCast(list, RollDiceActionType.REARM, source);
			}
		});
	}

	private void CheckAstralTinkererAchievement()
	{
		ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.RearmedSentinelAmount++;
		if (ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.RearmedAndRepairedSentinelAmount >= astralTinkererAchievementData.AchievementVariableAmount)
		{
			astralTinkererAchievementData.Unlock();
		}
	}

	public override void CastTarget(GameObject target, GameObject source)
	{
		if (ReferenceSingleton<BattleHandler>.Instance.IsSourceCompanions(source))
		{
			ReferenceSingleton<CursorHandler>.Instance.ToggleCursor(value: true);
		}
		CheckAstralTinkererAchievement();
		CompanionAbility component = target.GetComponent<CompanionAbility>();
		List<DiceInstance> diceInstances = SetupDiceInstances(component, ignoreCurrentDiceInstance: false);
		if (IsVFXEnabled())
		{
			PlaySFX();
		}
		SpawnVFX(GetVFXOwnerPosition(target), 4f);
		ReferenceSingleton<AssetsReference>.Instance.RerollAction.ExternalCast(diceInstances, RollDiceActionType.REARM, source);
	}

	private List<DiceInstance> SetupDiceInstances(CompanionAbility companionAbility, bool ignoreCurrentDiceInstance)
	{
		List<DiceInstance> diceInstancesToRoll = companionAbility.GetDiceInstancesToRoll();
		if (ignoreCurrentDiceInstance)
		{
			diceInstancesToRoll.Remove(ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance as DiceInstance);
		}
		EnableDiceInstances(diceInstancesToRoll);
		return diceInstancesToRoll;
	}

	private void EnableDiceInstances(List<DiceInstance> diceInstances)
	{
		for (int i = 0; i < diceInstances.Count; i++)
		{
			if (diceInstances[i] == ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance)
			{
				SetupCurrentActionInstance();
				continue;
			}
			diceInstances[i].ToggleActionEnabled(value: true);
			diceInstances[i].ToggleCompanionDice(value: true);
		}
	}

	private void SetupCurrentActionInstance()
	{
		(ReferenceSingleton<BattleHandler>.Instance.CurrentActionInstance as DiceInstance).SetupCurrentActionInstanceForRearmReroll();
	}
}
